import javax.persistence.*;
import java.io.Serializable;

/**
 * Entidad que representa un alumno persistente.
 * Se almacena directamente en ObjectDB.
 */
@Entity
@Table(name = "alumnos")
public class Alumno implements Serializable {

    private static final long serialVersionUID = 1L;

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private long id;

    @Column(nullable = false)
    private String nombre;

    @Column(nullable = false, unique = true)
    private String email;

    private double notaMedia;

    // Constructor vacio (requerido por JPA)
    public Alumno() {}

    // Constructor con datos
    public Alumno(String nombre, String email, double notaMedia) {
        this.nombre = nombre;
        this.email = email;
        this.notaMedia = notaMedia;
    }

    // Getters y setters
    public long getId() { return id; }
    public void setId(long id) { this.id = id; }

    public String getNombre() { return nombre; }
    public void setNombre(String nombre) { this.nombre = nombre; }

    public String getEmail() { return email; }
    public void setEmail(String email) { this.email = email; }

    public double getNotaMedia() { return notaMedia; }
    public void setNotaMedia(double notaMedia) { this.notaMedia = notaMedia; }

    @Override
    public String toString() {
        return String.format("Alumno{id=%d, nombre='%s', email='%s', nota=%.2f}",
            id, nombre, email, notaMedia);
    }
}

// Anotaciones clave:
// @Entity: marca la clase como entidad persistente
// @Table: nombre de la tabla (opcional por defecto)
// @Id: marca el campo como identificador unico
// @GeneratedValue: genera el ID automaticamente
// @Column: define propiedades de la columna
// Constructor vacio: JPA lo necesita para crear objetos desde la BD

import javax.persistence.*;
import java.util.List;

public class PrimeraPersistencia {

    public static void main(String[] args) {
        // 1. Crear el EntityManagerFactory
        EntityManagerFactory emf =
            Persistence.createEntityManagerFactory("objectdb:miBase.odb");

        // 2. Crear un EntityManager
        EntityManager em = emf.createEntityManager();

        try {
            // 3. GUARDAR un objeto
            em.getTransaction().begin();

            Alumno alumno1 = new Alumno("Ana Garcia", "ana@email.com", 8.5);
            Alumno alumno2 = new Alumno("Carlos Ruiz", "carlos@email.com", 7.2);
            Alumno alumno3 = new Alumno("Maria Lopez", "maria@email.com", 9.1);

            em.persist(alumno1);  // Guarda el objeto en la BD
            em.persist(alumno2);
            em.persist(alumno3);

            em.getTransaction().commit();
            System.out.println("Alumnos guardados correctamente.");

            // 4. CONSULTAR todos los objetos
            List<Alumno> alumnos = em
                .createQuery("SELECT a FROM Alumno a", Alumno.class)
                .getResultList();

            System.out.println("Alumnos en la base de datos:");
            for (Alumno a : alumnos) {
                System.out.println("  " + a);
            }

            // 5. CONSULTAR con filtro
            List<Alumno> aprobados = em
                .createQuery("SELECT a FROM Alumno a WHERE a.notaMedia >= 5.0", Alumno.class)
                .getResultList();

            System.out.println("\nAlumnos aprobados: " + aprobados.size());

        } finally {
            em.close();
            emf.close();
        }
    }
}

// Flujo:
// 1. EntityManagerFactory: abre la base de datos (costoso, se crea una vez)
// 2. EntityManager: sesion de trabajo (ligero, se crea por operacion)
// 3. begin/commit: transaccion (todo o nada)
// 4. persist(): guarda el objeto
// 5. JPQL: consulta orientada a objetos

