// VENTAJAS OODBMS:
// 1. Sin impedancia objeto-relacional: se guardan objetos directamente
// 2. Mejor rendimiento con objetos complejos (no hay JOINs)
// 3. Las relaciones se mantienen como referencias nativas
//
// INCONVENIENTES OODBMS:
// 1. Menos maduro que RDBMS (menos herramientas)
// 2. Consultas complejas mas dificiles (no hay SQL tan potente)
// 3. Menor compatibilidad con sistemas existentes
//
// RDBMS: INSERT INTO alumnos (nombre, email, nota_media) VALUES ('Ana', 'ana@email.com', 8.5)
// OODBMS: em.persist(new Alumno("Ana", "ana@email.com", 8.5))

// En los setters:
public void setNombre(String nombre) {
    if (nombre == null || nombre.isBlank()) {
        throw new IllegalArgumentException("El nombre no puede estar vacio");
    }
    this.nombre = nombre;
}

public void setEmail(String email) {
    if (email == null || !email.contains("@")) {
        throw new IllegalArgumentException("Email invalido: " + email);
    }
    this.email = email;
}

public void setNotaMedia(double nota) {
    if (nota < 0 || nota > 10) {
        throw new IllegalArgumentException("Nota invalida: " + nota);
    }
    this.notaMedia = nota;
}

