import javax.persistence.*;
import java.util.List;

public class EjemploActualizacion {

    public static void main(String[] args) {
        EntityManagerFactory emf =
            Persistence.createEntityManagerFactory("objectdb:miBase.odb");
        EntityManager em = emf.createEntityManager();

        try {
            // Crear alumnos
            em.getTransaction().begin();
            Alumno ana = new Alumno("Ana", "ana@email.com", 7.5);
            Alumno carlos = new Alumno("Carlos", "carlos@email.com", 6.0);
            em.persist(ana);
            em.persist(carlos);
            em.getTransaction().commit();

            System.out.println("ANTES:");
            System.out.println("  Ana: " + ana.getNotaMedia());
            System.out.println("  Carlos: " + carlos.getNotaMedia());

            // ACTUALIZAR: modificar atributos directamente
            em.getTransaction().begin();
            ana.setNotaMedia(9.0);  // se actualiza automaticamente
            carlos.setEmail("nuevo@email.com");
            em.getTransaction().commit();

            System.out.println("\nDESPUES:");
            System.out.println("  Ana: " + ana.getNotaMedia());
            System.out.println("  Carlos email: " + carlos.getEmail());

            // ACTUALIZAR masivo con JPQL (sin cargar objetos)
            em.getTransaction().begin();
            int actualizados = em
                .createQuery("UPDATE Alumno a SET a.notaMedia = a.notaMedia + 0.5")
                .executeUpdate();
            em.getTransaction().commit();
            System.out.println("\nActualizados " + actualizados + " alumnos (+0.5 nota)");

        } finally {
            em.close();
            emf.close();
        }
    }
}

// Claves:
// 1. Un objeto gestionado se actualiza automaticamente al modificar sus atributos
// 2. No es necesario llamar a un metodo especial para actualizar
// 3. UPDATE masivo con JPQL modifica multiples objetos sin cargarlos

import javax.persistence.*;
import java.util.List;

public class EjemploEliminacion {

    public static void main(String[] args) {
        EntityManagerFactory emf =
            Persistence.createEntityManagerFactory("objectdb:miBase.odb");
        EntityManager em = emf.createEntityManager();

        try {
            // Crear alumnos
            em.getTransaction().begin();
            em.persist(new Alumno("Ana", "ana@email.com", 8.5));
            em.persist(new Alumno("Carlos", "carlos@email.com", 7.2));
            em.persist(new Alumno("Maria", "maria@email.com", 9.1));
            em.getTransaction().commit();

            // ELIMINAR un objeto
            em.getTransaction().begin();
            Alumno carlos = em
                .createQuery(
                    "SELECT a FROM Alumno a WHERE a.nombre = 'Carlos'",
                    Alumno.class)
                .getSingleResult();
            em.remove(carlos); // Elimina de la BD
            em.getTransaction().commit();
            System.out.println("Carlos eliminado.");

            // ELIMINAR masivo con JPQL
            em.getTransaction().begin();
            int eliminados = em
                .createQuery("DELETE FROM Alumno a WHERE a.notaMedia < 5.0")
                .executeUpdate();
            em.getTransaction().commit();
            System.out.println("Eliminados " + eliminados + " alumnos suspensos.");

            // Verificar
            List<Alumno> restantes = em
                .createQuery("SELECT a FROM Alumno a", Alumno.class)
                .getResultList();
            System.out.println("Alumnos restantes: " + restantes.size());
            restantes.forEach(System.out::println);

        } finally {
            em.close();
            emf.close();
        }
    }
}

// Claves:
// 1. em.remove(objeto) elimina el objeto de la BD
// 2. DELETE masivo con JPQL elimina multiples objetos sin cargarlos
// 3. Si hay relaciones ( CascadeType.REMOVE ), se eliminan en cascada

Una **transaccion** es una operacion atomica: todo se ejecuta correctamente o nada se ejecuta. En JPA:

```java
em.getTransaction().begin();  // Iniciar transaccion
try {
    // Operaciones de persistencia
    em.persist(alumno1);
    em.persist(alumno2);
    em.getTransaction().commit();  // Confirmar cambios
} catch (Exception e) {
    em.getTransaction().rollback();  // Deshacer cambios
    throw e;
}
```

**Reglas de las transacciones:**
1. Siempre begin antes de persist/merge/remove
2. Si todo va bien: commit
3. Si hay error: rollback (deshace todo)
4. Despues de commit o rollback, se puede iniciar una nueva transaccion
5. Si no hay transaccion activa, las operaciones fallan

