Una de las grandes ventajas de OODBMS es que las relaciones entre objetos se manejan naturalmente. En JPA, se definen con anotaciones:

### @ManyToOne - Muchos a uno
```java
@Entity
public class Alumno {
    @Id @GeneratedValue
    private long id;
    private String nombre;

    @ManyToOne
    @JoinColumn(name = "curso_id")
    private Curso curso; // Un alumno pertenece a un curso
}
```

### @OneToMany - Uno a muchos
```java
@Entity
public class Curso {
    @Id @GeneratedValue
    private long id;
    private String nombre;

    @OneToMany(mappedBy = "curso", cascade = CascadeType.ALL)
    private List<Alumno> alumnos = new ArrayList<>();
    // Un curso tiene muchos alumnos
}
```

### @ManyToMany - Muchos a muchos
```java
@Entity
public class Alumno {
    @ManyToMany
    @JoinTable(
        name = "alumno_asignatura",
        joinColumns = @JoinColumn(name = "alumno_id"),
        inverseJoinColumns = @JoinColumn(name = "asignatura_id")
    )
    private List<Asignatura> asignaturas = new ArrayList<>();
}
```

### Tipos de cascada
| CascadeType | Descripcion |
|------------|-------------|
| ALL | Todas las operaciones se propagan |
| PERSIST | Guardar el padre guarda los hijos |
| REMOVE | Eliminar el padre elimina los hijos |
| MERGE | Actualizar el padre actualiza los hijos |
| REFRESH | Refrescar el padre refresca los hijos |

import javax.persistence.*;
import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;

// === ENTIDAD ALUMNO ===
@Entity
public class Alumno implements Serializable {
    @Id @GeneratedValue
    private long id;

    @Column(nullable = false)
    private String nombre;

    @Column(nullable = false, unique = true)
    private String email;

    private double notaMedia;

    @ManyToOne
    @JoinColumn(name = "curso_id")
    private Curso curso;

    public Alumno() {}
    public Alumno(String nombre, String email, double notaMedia) {
        this.nombre = nombre;
        this.email = email;
        this.notaMedia = notaMedia;
    }

    // Getters y setters
    public long getId() { return id; }
    public String getNombre() { return nombre; }
    public void setNombre(String nombre) { this.nombre = nombre; }
    public String getEmail() { return email; }
    public void setEmail(String email) { this.email = email; }
    public double getNotaMedia() { return notaMedia; }
    public void setNotaMedia(double notaMedia) { this.notaMedia = notaMedia; }
    public Curso getCurso() { return curso; }
    public void setCurso(Curso curso) { this.curso = curso; }

    @Override
    public String toString() {
        return String.format("Alumno{id=%d, nombre='%s', nota=%.2f}",
            id, nombre, notaMedia);
    }
}

// === ENTIDAD CURSO ===
@Entity
public class Curso implements Serializable {
    @Id @GeneratedValue
    private long id;

    @Column(nullable = false)
    private String nombre;

    private int horasTotales;
    private int capacidadMaxima;

    @OneToMany(mappedBy = "curso", cascade = CascadeType.ALL)
    private List<Alumno> alumnos = new ArrayList<>();

    public Curso() {}
    public Curso(String nombre, int horas, int capacidad) {
        this.nombre = nombre;
        this.horasTotales = horas;
        this.capacidadMaxima = capacidad;
    }

    public void addAlumno(Alumno alumno) {
        alumnos.add(alumno);
        alumno.setCurso(this);
    }

    // Getters y setters
    public long getId() { return id; }
    public String getNombre() { return nombre; }
    public int getHorasTotales() { return horasTotales; }
    public int getCapacidadMaxima() { return capacidadMaxima; }
    public List<Alumno> getAlumnos() { return new ArrayList<>(alumnos); }

    @Override
    public String toString() {
        return String.format("Curso{id=%d, nombre='%s', alumnos=%d}",
            id, nombre, alumnos.size());
    }
}

import javax.persistence.*;
import java.util.List;

public class AppCompleta {

    public static void main(String[] args) {
        EntityManagerFactory emf =
            Persistence.createEntityManagerFactory("objectdb:escuela.odb");
        EntityManager em = emf.createEntityManager();

        try {
            // 1. Crear cursos
            em.getTransaction().begin();
            Curso prog = new Curso("Programacion", 120, 30);
            Curso bd = new Curso("Base de Datos", 100, 25);
            em.persist(prog);
            em.persist(bd);
            em.getTransaction().commit();
            System.out.println("Cursos creados.");

            // 2. Crear alumnos y asignar a cursos
            em.getTransaction().begin();
            Alumno ana = new Alumno("Ana", "ana@email.com", 8.5);
            Alumno carlos = new Alumno("Carlos", "carlos@email.com", 7.2);
            Alumno maria = new Alumno("Maria", "maria@email.com", 9.1);

            prog.addAlumno(ana);
            prog.addAlumno(carlos);
            bd.addAlumno(maria);

            em.persist(ana);
            em.persist(carlos);
            em.persist(maria);
            em.getTransaction().commit();
            System.out.println("Alumnos creados y asignados.");

            // 3. Consultar alumnos de Programacion
            List<Alumno> alumnosProg = em
                .createQuery(
                    "SELECT a FROM Alumno a WHERE a.curso.nombre = :curso",
                    Alumno.class)
                .setParameter("curso", "Programacion")
                .getResultList();
            System.out.println("\nAlumnos de Programacion:");
            alumnosProg.forEach(a -> System.out.println("  " + a));

            // 4. Consultar curso con mas alumnos
            List<Curso> cursos = em
                .createQuery(
                    "SELECT c FROM Curso c ORDER BY c.alumnos.size DESC",
                    Curso.class)
                .getResultList();
            System.out.println("\nCursos por numero de alumnos:");
            cursos.forEach(c ->
                System.out.printf("  %s: %d alumnos%n", c.getNombre(), c.getAlumnos().size()));

            // 5. Media de notas por curso
            List<Object[]> medias = em
                .createQuery(
                    "SELECT a.curso.nombre, AVG(a.notaMedia) FROM Alumno a " +
                    "GROUP BY a.curso.nombre",
                    Object[].class)
                .getResultList();
            System.out.println("\nMedia de notas por curso:");
            medias.forEach(r ->
                System.out.printf("  %s: %.2f%n", r[0], r[1]));

        } finally {
            em.close();
            emf.close();
        }
    }
}

